const init = config => {
  const options = Object.assign({}, { openTrigger: 'data-micromodal-trigger' }, config)
  const triggers = [...document.querySelectorAll(`[${options.openTrigger}]`)]
  const triggerMap = generateTriggerMap(triggers, options.openTrigger)
  if (options.debugMode === true) {
    for (const targetModal in triggerMap) {
      if (!validateModalPresence(targetModal)) return
    }
  }
  if (activeModal) activeModal.removeEventListeners()
  for (const targetModal in triggerMap) {
    const triggersForModal = triggerMap[targetModal]
    const modalOptions = Object.assign({}, options, { targetModal, triggers: triggersForModal })
    new Modal(modalOptions) // eslint-disable-line no-new
  }
}

getFocusableNodes () {
  const selector = FOCUSABLE_ELEMENTS.join(',')
  const nodes = this.modal.querySelectorAll(selector)
  return Array.from(nodes)
}

